import math

def is_power_of_p(N, p):
    """Checks if N is a power of p (p^k for k >= 1)."""
    if N <= 0:
        return False
    if N == 1: # p^0 = 1. Since a, b >= 1 and p >= 3, N >= 2, so this shouldn't happen.
        return False

    # Check if p is the only prime factor
    while N > 1:
        if N % p != 0:
            return False
        N //= p
    return True

