primes = [3, 5, 7, 11]
max_val = 15

for p in primes:
    for a in range(1, max_val + 1):
        # Start b from a, respecting a <= b
        for b in range(a, max_val + 1):

            # Constraint 1: a == b (mod p)
            if (a - b) % p != 0:
                continue

            # Calculate N1 = a^(p-1) + b
            try:
                N1 = a**(p - 1) + b
            except OverflowError:
